public class Driver { static class DivideByZeroException extends Exception{DivideByZeroException(){super("Denominator cannot be 0");}}public static void main(String[]a){for(String s:new String[]{"10 / 0","abc / 2","20 / 4"}){System.out.println("Attempting: "+s);try{String[] p=s.split(" ");int x=Integer.parseInt(p[0]),y=Integer.parseInt(p[2]);if(y==0)throw new DivideByZeroException();System.out.println("Result: "+x/y);break;}catch(DivideByZeroException e){System.out.println("Error: "+e.getMessage());}catch(NumberFormatException e){System.out.println("Error: Invalid number entered");}finally{System.out.println("[Log] Completed operation attempt.\n");}}}}
